import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) { st.nextToken(); a[i] = (long) st.nval; }
        if (n <= 4) { System.out.println(0); return; }
        Arrays.sort(a);
        // Keep a contiguous window of n-3 sorted values: drop i from the left and 3-i from the right.
        long best = Long.MAX_VALUE;
        for (int i = 0; i < 4; i++) best = Math.min(best, a[n - 4 + i] - a[i]);
        System.out.println(best);
    }
}
